import requests
from requests.models import RequestEncodingMixin

class FileWrapper:
    def __init__(self, data):
        self._data = data
    def __getattr__(self, name):
        if name == 'read':
            return lambda length=None: self._data.read(length) if length is not None else self._data.read()
        raise AttributeError(name)

def test_getattr_file():
    import io
    content = b"hello world"
    fileobj = io.BytesIO(content)
    wrapper = FileWrapper(fileobj)

    # This should work if _encode_files correctly detects the wrapper as something that supports read()
    # We can use RequestEncodingMixin._encode_files directly since it's a static method
    try:
        body, content_type = RequestEncodingMixin._encode_files({'file': wrapper}, None)
        print("Success!")
        assert content in body
    except Exception as e:
        print(f"Failed with {type(e).__name__}: {e}")
        raise e

if __name__ == "__main__":
    test_getattr_file()
